def solve():
    H, W = map(int, sys.stdin.readline().split())
    S = [sys.stdin.readline().strip() for _ in range(H)]

    adj = [[[] for _ in range(W)] for _ in range(H)]
    is_magnet = [[False for _ in range(W)] for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if S[r][c] == '#':
                is_magnet[r][c] = True

    for r in range(H):
        for c in range(W):
            if not is_magnet[r][c]:
                # Check up
                if r > 0 and not is_magnet[r-1][c]:
                    adj[r][c].append((r-1, c))
                # Check down
                if r < H - 1 and not is_magnet[r+1][c]:
                    adj[r][c].append((r+1, c))
                # Check left
                if c > 0 and not is_magnet[r][c-1]:
                    adj[r][c].append((r, c-1))
                # Check right
                if c < W - 1 and not is_magnet[r][c+1]:
                    adj[r][c].append((r, c+1))

    max_degree = 0

    def dfs(r, c, visited):
        if visited[r][c]:
            return 0
        visited[r][c] = True
        count = 1
        for nr, nc in adj[r][c]:
            count += dfs(nr, nc, visited)
        return count

    for r in range(H):
        for c in range(W):
            if not is_magnet[r][c]:
                visited = [[False for _ in range(W)] for _ in range(H)]
                degree = dfs(r, c, visited)
                max_degree = max(max_degree, degree)

    print(max_degree)


def main():
    solve()

if __name__ == "__main__":
    main()
