def solve():
    polys_raw = []
    for _ in range(3):
        poly = []
        for _ in range(4):
            poly.append(input())
        polys_raw.append(poly)

    def extract_coords(poly_grid):
        coords = []
        for r in range(4):
            for c in range(4):
                if poly_grid[r][c] == '#':
                    coords.append((r, c))
        return coords

    def normalize_poly(coords):
        if not coords:
            return frozenset()
        min_r = min(r for r, c in coords)
        min_c = min(c for r, c in coords)
        return frozenset(((r - min_r, c - min_c) for r, c in coords))

    def rotate_poly(coords_set):
        rotated_coords = []
        if not coords_set:
            return frozenset()

        # Determine the current bounds
        min_r = min(r for r, c in coords_set)
        max_r = max(r for r, c in coords_set)
        min_c = min(c for r, c in coords_set)
        max_c = max(c for r, c in coords_set)

        # Rotation logic (90 degrees clockwise)
        # New_row = Old_col
        # New_col = Max_row - Old_row

        for r, c in coords_set:
            rotated_coords.append((c, (max_r + min_r) - r)) # Rotate around the center of the bounding box

        return normalize_poly(rotated_coords)


    def generate_all_orientations_and_positions(poly_coords):
        unique_orientations = {normalize_poly(poly_coords)}
        for _ in range(3): # Generate 3 more rotations
            poly_coords = rotate_poly(poly_coords)
            unique_orientations.add(poly_coords)

        all_placements = []
        for orientation in unique_orientations:
            if not orientation: # Handle empty polyominos
                continue

            # Find dimensions of the current orientation
            max_r_norm = max(r for r, c in orientation)
            max_c_norm = max(c for r, c in orientation)

            # Iterate through all possible top-left anchors for the normalized shape
            # (r_offset, c_offset) is where (0,0) of the normalized shape goes
            for r_offset in range(4 - max_r_norm):
                for c_offset in range(4 - max_c_norm):
                    placed_coords = frozenset(((r + r_offset, c + c_offset) for r, c in orientation))
                    all_placements.append(placed_coords)
        return all_placements

    poly_placements = []
    for poly_raw in polys_raw:
        initial_coords = extract_coords(poly_raw)
        poly_placements.append(generate_all_orientations_and_positions(initial_coords))

    # Backtracking search
    def can_fill(idx, current_grid):
        if idx == 3:
            # All polyominos placed, check if grid is full
            return all(all(cell == '#' for cell in row) for row in current_grid)

        for placement in poly_placements[idx]:
            new_grid = [row[:] for row in current_grid]

            is_valid_placement = True
            for r, c in placement:
                if 0 <= r < 4 and 0 <= c < 4:
                    if new_grid[r][c] == '#': # Overlap
                        is_valid_placement = False
                        break
                    new_grid[r][c] = '#'
                else: # Out of bounds (should be handled by generate_all_orientations_and_positions)
                    is_valid_placement = False
                    break

            if is_valid_placement:
                if can_fill(idx + 1, new_grid):
                    return True
        return False

    initial_empty_grid = [['.' for _ in range(4)] for _ in range(4)]

    if can_fill(0, initial_empty_grid):
        print("Yes")
    else:
        print("No")

solve()
