import sys

sys.setrecursionlimit(2000000)

MOD = 998244353


def solve():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    def is_valid(r, c):
        return 0 <= r < H and 0 <= c < W

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc):
                neighbors.append((nr, nc))
        return neighbors

    def bfs(start_r, start_c, visited, component_id):
        q = [(start_r, start_c)]
        visited[start_r][start_c] = component_id
        size = 1
        while q:
            r, c = q.pop(0)
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == '#' and visited[nr][nc] == 0:
                    visited[nr][nc] = component_id
                    size += 1
                    q.append((nr, nc))
        return size

    initial_visited = [[0 for _ in range(W)] for _ in range(H)]
    component_count = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#' and initial_visited[r][c] == 0:
                component_count += 1
                bfs(r, c, initial_visited, component_count)

    red_cells = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                red_cells.append((r, c))

    num_red_cells = len(red_cells)
    total_expected_components = 0

    for rr, rc in red_cells:
        # When (rr, rc) is repainted green
        new_component_count = component_count
        adjacent_green_components = set()
        newly_connected_to_existing = False

        for nr, nc in get_neighbors(rr, rc):
            if grid[nr][nc] == '#':
                comp_id = initial_visited[nr][nc]
                if comp_id != 0:
                    if comp_id not in adjacent_green_components:
                        adjacent_green_components.add(comp_id)
                        new_component_count -= 1
                        newly_connected_to_existing = True

        if not newly_connected_to_existing:
            new_component_count += 1

        total_expected_components = (total_expected_components + new_component_count) % MOD

    print(total_expected_components * pow(num_red_cells, MOD - 2, MOD) % MOD)


def main():
    solve()


if __name__ == "__main__":
    main()
