def smallestBeautifulString(s: str) -> str:
    n = len(s)
    best_s = s

    for i in range(n):
        for j in range(i, n):
            # Create a new string by modifying the substring s[i:j+1]
            temp_list = list(s)
            for k in range(i, j + 1):
                char_code = ord(temp_list[k])
                if char_code == ord('a'):
                    temp_list[k] = 'z'
                else:
                    temp_list[k] = chr(char_code - 1)

            current_s = "".join(temp_list)

            # Compare lexicographically and update if smaller
            if current_s < best_s:
                best_s = current_s

    return best_s
