def count_right_triangles(grid):
    rows = len(grid)
    cols = len(grid[0])
    count = 0

    # Precompute the number of 1s in each row and column
    row_ones = [0] * rows
    col_ones = [0] * cols

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                row_ones[r] += 1
                col_ones[c] += 1

    # Iterate through each cell
    for r in range(rows):
        for c in range(cols):
            # If the current cell is a '1', it can be the corner of a right triangle
            if grid[r][c] == 1:
                # The number of right triangles with (r, c) as the corner
                # is (number of 1s in row r - 1) * (number of 1s in col c - 1)
                # We subtract 1 because we exclude the corner cell itself from the other two points
                if row_ones[r] > 1 and col_ones[c] > 1:
                    count += (row_ones[r] - 1) * (col_ones[c] - 1)

    return count
```

