def beautiful_integers(low: int, high: int, k: int) -> int:
    def is_beautiful(n: int, k: int) -> bool:
        if n % k != 0:
            return False

        s_n = str(n)
        even_count = 0
        odd_count = 0
        for digit_char in s_n:
            digit = int(digit_char)
            if digit % 2 == 0:
                even_count += 1
            else:
                odd_count += 1
        return even_count == odd_count

    count = 0
    for num in range(low, high + 1):
        if is_beautiful(num, k):
            count += 1
    return count
