def minimum_balanced_partitions(s):
    """
    Given a string s, you need to partition it into one or more balanced substrings.
    A balanced string is a string where each character in the string occurs the same number of times.
    Return the minimum number of substrings that you can partition s into.

    Args:
        s: The input string.

    Returns:
        The minimum number of balanced substrings.
    """
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    def is_balanced(substring):
        if not substring:
            return True
        counts = {}
        for char in substring:
            counts[char] = counts.get(char, 0) + 1

        first_count = None
        for count in counts.values():
            if first_count is None:
                first_count = count
            elif count != first_count:
                return False
        return True

    for i in range(1, n + 1):
        for j in range(i):
            substring = s[j:i]
            if is_balanced(substring):
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]
