def solve():
    def max_distance(pts):
        max_d = 0
        for i in range(len(pts)):
            for j in range(i + 1, len(pts)):
                dist = abs(pts[i][0] - pts[j][0]) + abs(pts[i][1] - pts[j][1])
                max_d = max(max_d, dist)
        return max_d

    def min_max_Manhattan_distance(points):
        n = len(points)
        min_max_dist = float('inf')

        for i in range(n):
            temp_points = points[:i] + points[i+1:]
            current_max_dist = max_distance(temp_points)
            min_max_dist = min(min_max_dist, current_max_dist)

        return min_max_dist

    return min_max_Manhattan_distance
