def distributeCandies(n: int, limit: int) -> int:
    count = 0
    # Iterate through all possible candy distributions for child1
    for c1 in range(min(n, limit) + 1):
        # Iterate through all possible candy distributions for child2
        for c2 in range(min(n - c1, limit) + 1):
            c3 = n - c1 - c2
            # Check if child3's candy count is within the limit
            if 0 <= c3 <= limit:
                count += 1
    return count
