def solve():
    A = []
    for _ in range(3):
        A.append(list(map(int, input().split())))

    # Constants for players
    TAKAHASHI = 0
    AOKI = 1

    # Represents an empty cell, Takahashi's cell, Aoki's cell
    EMPTY = -1
    RED = TAKAHASHI
    BLUE = AOKI

    initial_board = [[EMPTY for _ in range(3)] for _ in range(3)]

    # Scores
    initial_takahashi_score = 0
    initial_aoki_score = 0

    # Memoization dictionary for minimax
    memo = {}

    def is_game_over(board):
        # Check rows
        for i in range(3):
            if board[i][0] != EMPTY and board[i][0] == board[i][1] == board[i][2]:
                return True, board[i][0]  # Winner found

        # Check columns
        for j in range(3):
            if board[0][j] != EMPTY and board[0][j] == board[1][j] == board[2][j]:
                return True, board[0][j]  # Winner found

        # Check diagonals
        if board[0][0] != EMPTY and board[0][0] == board[1][1] == board[2][2]:
            return True, board[0][0]  # Winner found
        if board[0][2] != EMPTY and board[0][2] == board[1][1] == board[2][0]:
            return True, board[0][2]  # Winner found

        # Check if all cells are filled
        for r in range(3):
            for c in range(3):
                if board[r][c] == EMPTY:
                    return False, None # Game not over, no winner yet

        # All cells filled, no 3 in a row
        return True, -1 # Game over, no 3-in-a-row winner, score decides

    def evaluate_winner(takahashi_score, aoki_score):
        if takahashi_score > aoki_score:
            return TAKAHASHI
        elif aoki_score > takahashi_score:
            return AOKI
        else:
            # This case should technically not happen due to odd sum of A_ij
            # For robustness, we can handle it or assume constraints prevent it.
            # Based on the problem statement, sum is odd, meaning total score is odd.
            # So scores cannot be equal.
            # Example: if total is odd, T+A = odd. If T=A, T+T = odd, 2T = odd, impossible.
            return None # Should not be reached

    def minimax(board, current_player, takahashi_score, aoki_score, white_cells_left):
        board_tuple = tuple(tuple(row) for row in board)
        state_key = (board_tuple, current_player, takahashi_score, aoki_score)

        if state_key in memo:
            return memo[state_key]

        game_over, winner_color = is_game_over(board)

        if game_over:
            if winner_color == RED:
                # Takahashi wins by 3-in-a-row
                return (10**18) # Very large score for Takahashi
            elif winner_color == BLUE:
                # Aoki wins by 3-in-a-row
                return (-10**18) # Very small score for Takahashi
            elif white_cells_left == 0:
                # All cells filled, no 3-in-a-row winner
                calculated_winner = evaluate_winner(takahashi_score, aoki_score)
                if calculated_winner == TAKAHASHI:
                    return (10**17) # Game over by full board, Takahashi wins
                elif calculated_winner == AOKI:
                    return (-10**17) # Game over by full board, Aoki wins
                else: # Should not happen
                    return 0

        best_score = float('-inf') if current_player == TAKAHASHI else float('inf')

        for r in range(3):
            for c in range(3):
                if board[r][c] == EMPTY:
                    # Make a move
                    new_board = [row[:] for row in board]
                    new_takahashi_score = takahashi_score
                    new_aoki_score = aoki_score

                    if current_player == TAKAHASHI:
                        new_board[r][c] = RED
                        new_takahashi_score += A[r][c]
                    else: # current_player == AOKI
                        new_board[r][c] = BLUE
                        new_aoki_score += A[r][c]

                    # Recurse
                    score = minimax(new_board, 1 - current_player, new_takahashi_score, new_aoki_score, white_cells_left - 1)

                    # Update best score
                    if current_player == TAKAHASHI:
                        best_score = max(best_score, score)
                    else: # current_player == AOKI
                        best_score = min(best_score, score)

        memo[state_key] = best_score
        return best_score

    final_score = minimax(initial_board, TAKAHASHI, initial_takahashi_score, initial_aoki_score, 9)

    # Determine winner based on the final score returned by minimax
    if final_score > 0:
        print("Takahashi")
    else:
        print("Aoki")

