def countPrefixSuffixPairs(words: list[str]) -> int:
    """
    Counts the number of index pairs (i, j) such that i < j, and words[i]
    is both a prefix and a suffix of words[j].
    """
    def isPrefixAndSuffix(str1: str, str2: str) -> bool:
        """
        Checks if str1 is both a prefix and a suffix of str2.
        """
        if len(str1) > len(str2):
            return False
        return str2.startswith(str1) and str2.endswith(str1)

    count = 0
    n = len(words)
    for i in range(n):
        for j in range(i + 1, n):
            if isPrefixAndSuffix(words[i], words[j]):
                count += 1
    return count
