def shortestSubstrings(arr):
    n = len(arr)
    answer = [""] * n

    for i in range(n):
        shortest_unique_substring = ""
        min_len = float('inf')

        for length in range(1, len(arr[i]) + 1):
            for j in range(len(arr[i]) - length + 1):
                substring = arr[i][j : j + length]
                is_unique = True

                for k in range(n):
                    if i == k:
                        continue
                    if substring in arr[k]:
                        is_unique = False
                        break

                if is_unique:
                    if length < min_len:
                        min_len = length
                        shortest_unique_substring = substring
                    elif length == min_len:
                        if shortest_unique_substring == "" or substring < shortest_unique_substring:
                            shortest_unique_substring = substring
            if shortest_unique_substring != "" and min_len == length:
                break

        answer[i] = shortest_unique_substring
    return answer
