def findLongestCommonSuffix(wordsContainer, wordsQuery):
    """
    Finds the index of the string in wordsContainer that has the longest common suffix
    with each string in wordsQuery, with tie-breaking rules.

    Args:
        wordsContainer: A list of strings.
        wordsQuery: A list of strings.

    Returns:
        A list of integers, where ans[i] is the index of the best matching string
        in wordsContainer for wordsQuery[i].
    """
    n = len(wordsContainer)
    m = len(wordsQuery)
    ans = [-1] * m

    # Precompute reversed words and a trie for efficient suffix searching
    reversed_container = [word[::-1] for word in wordsContainer]

    trie = {}
    for i, word in enumerate(reversed_container):
        node = trie
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
            # Store (length, index) at each node to track best candidate
            if 'best' not in node:
                node['best'] = (len(word), i)
            else:
                current_best_len, current_best_idx = node['best']
                if len(word) < current_best_len:
                    node['best'] = (len(word), i)
                elif len(word) == current_best_len and i < current_best_idx:
                    node['best'] = (len(word), i)

    for i, query_word in enumerate(wordsQuery):
        reversed_query = query_word[::-1]
        node = trie
        best_match_len = 0
        best_match_idx = -1

        # Track the best candidate encountered so far from trie traversal
        initial_best_candidate = (-1, -1) # (length, index)

        for char in reversed_query:
            if char in node:
                node = node[char]
                if 'best' in node:
                    current_candidate_len, current_candidate_idx = node['best']

                    # Compare with the overall best candidate found in this query
                    if initial_best_candidate == (-1, -1):
                        initial_best_candidate = node['best']
                    else:
                        prev_best_len, prev_best_idx = initial_best_candidate
                        if current_candidate_len < prev_best_len:
                            initial_best_candidate = node['best']
                        elif current_candidate_len == prev_best_len and current_candidate_idx < prev_best_idx:
                            initial_best_candidate = node['best']
            else:
                break

        # If no common suffix found, the best match is the one with the smallest length
        # among all container words. If multiple have the same smallest length, pick the
        # earliest occurring one.
        if initial_best_candidate == (-1, -1):
            overall_best_len = float('inf')
            overall_best_idx = -1
            for idx, word in enumerate(wordsContainer):
                if len(word) < overall_best_len:
                    overall_best_len = len(word)
                    overall_best_idx = idx
                elif len(word) == overall_best_len and idx < overall_best_idx:
                    overall_best_idx = idx
            ans[i] = overall_best_idx
        else:
            ans[i] = initial_best_candidate[1]

    return ans
