    results = []

    for i in range(1, n + 1):
        s = sys.stdin.readline().strip()

        # Check if s is equal to t_prime
        if s == t_prime:
            results.append(i)
            continue

        # Check if t_prime is obtained by inserting one character into s
        if len(t_prime) == len(s) + 1:

            diff_count = 0
            s_ptr = 0
            t_ptr = 0

            while s_ptr < len(s) and t_ptr < len(t_prime):
                if s[s_ptr] != t_prime[t_ptr]:
                    diff_count += 1
                    t_ptr += 1
                    if diff_count > 1:
                        break
                else:
                    s_ptr += 1
                    t_ptr += 1

            if diff_count <= 1:
                results.append(i)
            continue

        # Check if t_prime is obtained by deleting one character from s
        if len(t_prime) == len(s) - 1:

            diff_count = 0
            s_ptr = 0
            t_ptr = 0

            while s_ptr < len(s) and t_ptr < len(t_prime):
                if s[s_ptr] != t_prime[t_ptr]:
                    diff_count += 1
                    s_ptr += 1
                    if diff_count > 1:
                        break
                else:
                    s_ptr += 1
                    t_ptr += 1

            if diff_count <= 1:
                results.append(i)
            continue

        # Check if t_prime is obtained by changing one character in s
        if len(t_prime) == len(s):

            diff_count = 0
            for j in range(len(s)):
                if s[j] != t_prime[j]:
                    diff_count += 1
                    if diff_count > 1:
                        break

            if diff_count == 1:
                results.append(i)
            continue

