from functools import lru_cache

def min_len_join_ops(words):
    n = len(words)

    @lru_cache(None)
    def solve(index, current_string):
        if index == n:
            return len(current_string)

        word = words[index]

        # Option 1: join(current_string, word)
        len1 = float('inf')
        if current_string:
            if current_string[-1] == word[0]:
                len1 = solve(index + 1, current_string[:-1] + word)
            else:
                len1 = solve(index + 1, current_string + word)
        else:
            len1 = solve(index + 1, word)


        # Option 2: join(word, current_string)
        len2 = float('inf')
        if current_string:
            if words[index][-1] == current_string[0]:
                len2 = solve(index + 1, word + current_string[1:])
            else:
                len2 = solve(index + 1, word + current_string)
        else:
            len2 = solve(index + 1, word)

        return min(len1, len2)

    return solve(1, words[0])
