import sys

def solve():
    n, m = map(int, sys.stdin.readline().split())

    # Adjacency list to represent the superiority relation
    # stronger_than[i] will store a set of programmers that person i is stronger than
    stronger_than = [set() for _ in range(n + 1)]

    for _ in range(m):
        a, b = map(int, sys.stdin.readline().split())
        stronger_than[a].add(b)

    # We can use a matrix or list of lists to keep track of who is stronger than whom
    # floyd-warshall can compute transitive closure to determine all known superiorities

    # Initialize a reachability matrix. 
    # For 1-based indexing, we'll use an (n+1) x (n+1) matrix.
    # adj[i][j] = True if i is known to be stronger than j
    adj = [[False for _ in range(n + 1)] for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in stronger_than[i]:
            adj[i][j] = True

    # Apply Floyd-Warshall to compute transitive closure
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if adj[i][k] and adj[k][j]:
                    adj[i][j] = True

    # Count how many people each person is known to be stronger than
    # If a person is stronger than everyone else (n-1 people), they are the strongest
    stronger_counts = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i != j and adj[i][j]:
                stronger_counts[i] += 1

    # Find potential strongest programmers
    potential_strongest = []
    for i in range(1, n + 1):
        if stronger_counts[i] == n - 1:
            potential_strongest.append(i)

    # If exactly one person is stronger than everyone else, that's the unique strongest
    if len(potential_strongest) == 1:
        print(potential_strongest[0])
    else:
        # Otherwise, we cannot uniquely determine the strongest programmer
        print(-1)

