def stableBinaryArrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7

    dp = {}

    # dp((last_char, current_length_of_last_char_runs, remaining_zeros, remaining_ones)) returns the number of stable arrays
    def solve(last_char, current_run_length, r_zeros, r_ones):
        if (last_char, current_run_length, r_zeros, r_ones) in dp:
            return dp[(last_char, current_run_length, r_zeros, r_ones)]

        if r_zeros == 0 and r_ones == 0:
            return 1

        ans = 0

        # Try appending a '0'
        if last_char == 0:
            if current_run_length < limit and r_zeros > 0:
                ans = (ans + solve(0, current_run_length + 1, r_zeros - 1, r_ones)) % MOD
            if r_ones > 0:
                ans = (ans + solve(1, 1, r_zeros, r_ones - 1)) % MOD
        else:  # last_char == 1
            if r_zeros > 0:
                ans = (ans + solve(0, 1, r_zeros - 1, r_ones)) % MOD
            if current_run_length < limit and r_ones > 0:
                ans = (ans + solve(1, current_run_length + 1, r_zeros, r_ones - 1)) % MOD

        dp[(last_char, current_run_length, r_zeros, r_ones)] = ans
        return ans

    # Initialize dp table for memoization
    dp = {}

    # Start with '0'
    ans_start_0 = solve(0, 1, zero - 1, one) if zero > 0 else 0
    # Start with '1'
    ans_start_1 = solve(1, 1, zero, one - 1) if one > 0 else 0

    return (ans_start_0 + ans_start_1) % MOD

