def solve():
    H, W, T = map(int, input().split())
    grid = [input() for _ in range(H)]

    start_row, start_col = -1, -1
    goal_row, goal_col = -1, -1
    candy_locations = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                start_row, start_col = r, c
            elif grid[r][c] == 'G':
                goal_row, goal_col = r, c
            elif grid[r][c] == 'o':
                candy_locations.append((r, c))

    num_candies = len(candy_locations)
    all_locations = [(start_row, start_col)] + candy_locations + [(goal_row, goal_col)]
    num_points = len(all_locations)

    # Precompute distances between all important points (S, G, candies) using BFS
    dist_matrix = [[float('inf')] * num_points for _ in range(num_points)]

    def bfs(start_r, start_c):
        q = [(start_r, start_c, 0)]
        visited = [[False] * W for _ in range(H)]
        visited[start_r][start_c] = True
        distances = {}

        while q:
            r, c, d = q.pop(0)
            distances[(r, c)] = d

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and not visited[nr][nc]:
                    visited[nr][nc] = True
                    q.append((nr, nc, d + 1))
        return distances

    point_of_interest_distances = []
    for i, (sr, sc) in enumerate(all_locations):
        point_of_interest_distances.append(bfs(sr, sc))

    for i in range(num_points):
        for j in range(num_points):
            target_r, target_c = all_locations[j]
            if (target_r, target_c) in point_of_interest_distances[i]:
                dist_matrix[i][j] = point_of_interest_distances[i][(target_r, target_c)]

    # If direct path from S to G is impossible or too long, output -1.
    if dist_matrix[0][num_points - 1] == float('inf') or dist_matrix[0][num_points - 1] > T:
        # Check if any candy can be collected before time runs out for S to G
        max_candies_no_dist_cost = -1
        if dist_matrix[0][num_points - 1] != float('inf'):
            max_candies_no_dist_cost = 0

        for k in range(1, num_points - 1): # Iterate through candies
            dist_s_to_candy = dist_matrix[0][k]
            dist_candy_to_g = dist_matrix[k][num_points - 1]
            if dist_s_to_candy != float('inf') and dist_candy_to_g != float('inf'):
                if dist_s_to_candy + dist_candy_to_g <= T:
                    max_candies_no_dist_cost = max(max_candies_no_dist_cost, 1)

        if max_candies_no_dist_cost == -1:
            print(-1)
            return

        # If S to G path is impossible or too long, we can still potentially visit candies
        # if the total time to visit some candies and reach G is within T.
        # This part requires TSP-like dynamic programming.

        # dp[mask][i] = minimum time to visit candies represented by 'mask' and end at candy 'i'
        # 'mask' is a bitmask of length num_candies
        # 'i' is the index of the candy (0 to num_candies-1), corresponding to all_locations[1] to all_locations[num_candies]
        dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

        # Base cases: Starting from S and visiting the first candy
        for i in range(num_candies):
            dist_s_to_candy_i = dist_matrix[0][i + 1]
            if dist_s_to_candy_i != float('inf'):
                dp[1 << i][i] = dist_s_to_candy_i

        # Iterate through increasing number of set bits in mask
        for mask in range(1 << num_candies):
            for i in range(num_candies):
                if (mask >> i) & 1:  # If candy 'i' is in the current mask
                    for j in range(num_candies):
                        if not ((mask >> j) & 1): # If candy 'j' is not yet in the mask
                            new_mask = mask | (1 << j)
                            dist_candy_i_to_j = dist_matrix[i + 1][j + 1]
                            if dp[mask][i] != float('inf') and dist_candy_i_to_j != float('inf'):
                                dp[new_mask][j] = min(dp[new_mask][j], dp[mask][i] + dist_candy_i_to_j)

        max_collected_candies = -1
        if max_candies_no_dist_cost != -1:
            max_collected_candies = max_candies_no_dist_cost

        # Check paths that end at G
        for mask in range(1 << num_candies):
            for i in range(num_candies):
                if dp[mask][i] != float('inf'):
                    dist_last_candy_to_g = dist_matrix[i + 1][num_points - 1]
                    if dp[mask][i] + dist_last_candy_to_g <= T:
                        num_collected = bin(mask).count('1')
                        max_collected_candies = max(max_collected_candies, num_collected)
        print(max_collected_candies)
        return


    # Dijkstra to solve the TSP-like problem on candies
    # State: (number of candies collected, last candy visited, mask of visited candies)
    # We want to maximize the number of candies collected within time T.
    # Since we want to *maximize* candies, and DP state usually minimizes cost,
    # we can reframe this: find the minimum time to achieve a certain number of candies.
    # Or, use Dijkstra where cost is negative time to explore states that *can* lead to more candies.

    # Let's use Dijkstra to find minimum time to reach end state for each candy mask.
    # State in heap: (current_time, current_node_idx, mask)
    # current_node_idx: 0 for S, 1 to num_candies for candies, num_points-1 for G.
    # We are interested in reaching G.

    # We will use Dijkstra to find the minimum time to reach any state (candy_mask, last_candy_index)
    # State: (mask, last_candy_bitmask_index) where last_candy_bitmask_index is the index of the last candy visited (0 to num_candies-1)
    # dp[mask][last_candy_idx] = minimum time to achieve this state.
    # Initial state is before visiting any candy, from S.
    dp = [[float('inf')] * num_candies for _ in range(1 << num_candies)]

    # Start from S to each candy
    for i in range(num_candies):
        dist_s_to_candy_i = dist_matrix[0][i + 1]
        if dist_s_to_candy_i != float('inf'):
            dp[1 << i][i] = dist_s_to_candy_i

    # Use Dijkstra's or BFS-like approach for DP transitions
    # We can iterate through masks by number of set bits.
    # The number of candies is at most 18, so 2^18 is manageable.

    pq = []
    for i in range(num_candies):
        if dp[1 << i][i] != float('inf'):
            heapq.heappush(pq, (dp[1 << i][i], i, 1 << i)) # (time, last_candy_index, mask)

    while pq:
        current_time, last_candy_idx, mask = heapq.heappop(pq)

        if current_time > dp[mask][last_candy_idx]:
            continue

        # Transition to the next candy
        for next_candy_idx in range(num_candies):
            if not ((mask >> next_candy_idx) & 1): # If next candy is not yet visited
                dist_between_candies = dist_matrix[last_candy_idx + 1][next_candy_idx + 1]
                if dist_between_candies != float('inf'):
                    new_time = current_time + dist_between_candies
                    new_mask = mask | (1 << next_candy_idx)
                    if new_time < dp[new_mask][next_candy_idx]:
                        dp[new_mask][next_candy_idx] = new_time
                        heapq.heappush(pq, (new_time, next_candy_idx, new_mask))

    max_collected = -1

    # Check paths that reach G after visiting candies
    for mask in range(1 << num_candies):
        for last_candy_idx in range(num_candies):
            if dp[mask][last_candy_idx] != float('inf'):
                dist_last_candy_to_g = dist_matrix[last_candy_idx + 1][num_points - 1]
                if dist_last_candy_to_g != float('inf'):
                    total_time = dp[mask][last_candy_idx] + dist_last_candy_to_g
                    if total_time <= T:
                        num_collected = bin(mask).count('1')
                        max_collected = max(max_collected, num_collected)

    # Consider the case where no candies are collected but S can reach G within T.
    dist_s_to_g = dist_matrix[0][num_points - 1]
    if dist_s_to_g != float('inf') and dist_s_to_g <= T:
        max_collected = max(max_collected, 0)


    print(max_collected)

