def min_equal_sum(nums1, nums2):
    sum1 = sum(nums1)
    sum2 = sum(nums2)
    zeros1 = nums1.count(0)
    zeros2 = nums2.count(0)

    # Calculate the minimum possible sum for each array if all zeros are replaced with 1s
    min_sum1 = sum1 + zeros1
    min_sum2 = sum2 + zeros2

    if zeros1 == 0 and zeros2 == 0:
        return sum1 if sum1 == sum2 else -1
    elif zeros1 == 0:
        if sum1 >= min_sum2:
            return sum1
        else:
            return -1
    elif zeros2 == 0:
        if sum2 >= min_sum1:
            return sum2
        else:
            return -1
    else:  # Both arrays have zeros
        return max(min_sum1, min_sum2)
