def color_array(n: int, queries: list[list[int]]) -> list[int]:
    nums = [0] * n
    answer = []
    current_same_color_pairs = 0

    def check_and_update(idx, old_val, new_val, current_count):
        count_change = 0
        # Check left neighbor
        if idx > 0:
            if nums[idx - 1] == old_val and old_val != 0:
                count_change -= 1
            if nums[idx - 1] == new_val and new_val != 0:
                count_change += 1
        # Check right neighbor
        if idx < n - 1:
            if nums[idx + 1] == old_val and old_val != 0:
                count_change -= 1
            if nums[idx + 1] == new_val and new_val != 0:
                count_change += 1
        return current_count + count_change

    for index_i, color_i in queries:
        old_color = nums[index_i]

        # Before updating, subtract contributions from old color
        # Check left
        if index_i > 0 and nums[index_i - 1] == old_color and old_color != 0:
            current_same_color_pairs -= 1
        # Check right
        if index_i < n - 1 and nums[index_i + 1] == old_color and old_color != 0:
            current_same_color_pairs -= 1

        nums[index_i] = color_i

        # After updating, add contributions from new color
        # Check left
        if index_i > 0 and nums[index_i - 1] == color_i and color_i != 0:
            current_same_color_pairs += 1
        # Check right
        if index_i < n - 1 and nums[index_i + 1] == color_i and color_i != 0:
            current_same_color_pairs += 1

        answer.append(current_same_color_pairs)

    return answer
