def countCompleteSubstrings(word: str, k: int) -> int:
    n = len(word)
    count = 0

    for i in range(n):
        char_counts = {}
        for j in range(i, n):
            char = word[j]
            char_counts[char] = char_counts.get(char, 0) + 1

            # Check the adjacent character difference constraint
            valid_adjacent = True
            if j > i:
                prev_char = word[j - 1]
                if abs(ord(char) - ord(prev_char)) > 2:
                    valid_adjacent = False
                    break

            if not valid_adjacent:
                break

            # Check if all characters appear exactly k times
            all_k = True
            if len(char_counts) > 0:
                for char_count in char_counts.values():
                    if char_count != k:
                        all_k = False
                        break

                if all_k and len(char_counts) * k == (j - i + 1):
                    count += 1
    return count
