def longestAlternatingSubarray(nums: list[int]) -> int:
    max_length = -1
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            current_subarray = nums[i : j + 1]
            m = len(current_subarray)

            if m <= 1:
                continue

            is_alternating = True
            for k in range(1, m):
                expected_diff = 1 if k % 2 == 1 else -1
                if current_subarray[k] - current_subarray[k - 1] != expected_diff:
                    is_alternating = False
                    break

            if is_alternating:
                max_length = max(max_length, m)

    return max_length
