def canSortArray(nums: list[int]) -> bool:
    def countSetBits(n: int) -> int:
        count = 0
        while n > 0:
            n &= (n - 1)
            count += 1
        return count

    n = len(nums)
    bit_counts = [countSetBits(num) for num in nums]

    for i in range(n):
        for j in range(0, n - 1 - i):
            if nums[j] > nums[j + 1]:
                if bit_counts[j] == bit_counts[j + 1]:
                    nums[j], nums[j + 1] = nums[j + 1], nums[j]
                    bit_counts[j], bit_counts[j + 1] = bit_counts[j + 1], bit_counts[j]
                else:
                    return False
