    dsu = DSU(n)

    prime_to_index = {}

    for i, num in enumerate(nums):
        factors = prime_factors(num)
        for factor in factors:
            if factor in prime_to_index:
                dsu.union(i, prime_to_index[factor])
            else:
                prime_to_index[factor] = i

    root = dsu.find(0)
    for i in range(1, n):
        if dsu.find(i) != root:
            return False

