def lexicographicallySmallestArray(nums: list[int], limit: int) -> list[int]:
    n = len(nums)
    if n == 1:
        return nums

    indexed_nums = sorted([(num, i) for i, num in enumerate(nums)])
    parent = list(range(n))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_j] = root_i

    for i in range(n - 1):
        if abs(indexed_nums[i][0] - indexed_nums[i + 1][0]) <= limit:
            union(indexed_nums[i][1], indexed_nums[i + 1][1])

    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = {'original_indices': [], 'values': []}
        components[root]['original_indices'].append(i)
        components[root]['values'].append(nums[i])

    result = [0] * n
    for root in components:
        original_indices = sorted(components[root]['original_indices'])
        values = sorted(components[root]['values'])
        for i in range(len(original_indices)):
            result[original_indices[i]] = values[i]

    return result
