import sys

def solve():
    N = int(sys.stdin.readline())
    R = sys.stdin.readline().strip()
    C = sys.stdin.readline().strip()

    def is_valid(grid):
        # Check row counts
        for r in range(N):
            counts = {'A': 0, 'B': 0, 'C': 0}
            for c in range(N):
                if grid[r][c] != '.':
                    counts[grid[r][c]] += 1
            if counts['A'] != 1 or counts['B'] != 1 or counts['C'] != 1:
                return False

        # Check column counts
        for c in range(N):
            counts = {'A': 0, 'B': 0, 'C': 0}
            for r in range(N):
                if grid[r][c] != '.':
                    counts[grid[r][c]] += 1
            if counts['A'] != 1 or counts['B'] != 1 or counts['C'] != 1:
                return False

        # Check leftmost characters in rows
        for r in range(N):
            leftmost = None
            for c in range(N):
                if grid[r][c] != '.':
                    leftmost = grid[r][c]
                    break
            if leftmost != R[r]:
                return False

        # Check topmost characters in columns
        for c in range(N):
            topmost = None
            for r in range(N):
                if grid[r][c] != '.':
                    topmost = grid[r][c]
                    break
            if topmost != C[c]:
                return False
        return True

    def find_permutation(row_idx, current_grid):
        if row_idx == N:
            if is_valid(current_grid):
                return True
            return False

        # Try assigning characters for the current row
        for p in permutations("ABC"):
            # We need to place A, B, C in specific columns to satisfy row/col constraints
            # This is a simplified approach; a full backtrack might be needed for complex searches.
            # For N=3 to 5, a brute-force of permutations for each character's placement
            # within a row might still explode.
            # A more disciplined backtracking approach:
            # For each row, try placing 'A', 'B', 'C' in available spots.

            temp_grid = [list(row) for row in current_grid]
            temp_grid[row_idx] = list(p) # This will need to be more sophisticated

            # The permutation approach directly applied to rows is too simple.
            # We need to place characters considering column constraints.

            # Let's redefine the state: grid, current row, columns filled status for A, B, C
            # A better approach would be to have a recursive function that tries to fill
            # cells one by one, or row by row, with constraint checking at each step.

            # For N=3 to 5, a column-by-column or cell-by-cell backtracking might be more feasible.
            # Let's try a cell-by-cell backtracking approach.

            return backtrack(0, 0, [[d for d in row] for row in current_grid]) # Start over with better backtrack

    def backtrack(r, c, grid):
        if r == N:
            if is_valid(grid):
                solutions.append(["".join(row) for row in grid])
            return

        next_r, next_c = (r, c + 1) if c + 1 < N else (r + 1, 0)

        # If cell is already filled (from a previous step, not applicable in this simple structure but good for general backtrack)
        # For this problem, we are constructing from scratch.

        # Try placing characters
        chars_to_try = ['A', 'B', 'C']
        for char in chars_to_try:
            grid[r][c] = char
            if check_partial(grid, r, c):
                backtrack(next_r, next_c, grid)
            grid[r][c] = '.' # Backtrack

        # Try leaving it empty
        grid[r][c] = '.'
        if check_partial(grid, r, c): # The check_partial here is less meaningful for empty cell
             backtrack(next_r, next_c, grid)
        grid[r][c] = '.' # Backtrack if we don't proceed (this line is redundant for empty cell)


    def check_partial(grid, current_r, current_c):
        # Check row constraints for the current row and previous columns
        row_counts = {'A': 0, 'B': 0, 'C': 0}
        leftmost_in_row = None
        for c in range(N):
            if grid[current_r][c] != '.':
                row_counts[grid[current_r][c]] += 1
                if leftmost_in_row is None:
                    leftmost_in_row = grid[current_r][c]
        if any(count > 1 for count in row_counts.values()):
            return False
        if leftmost_in_row is not None and leftmost_in_row != R[current_r]:
            return False

        # Check column constraints for the current column and previous rows
        col_counts = {'A': 0, 'B': 0, 'C': 0}
        topmost_in_col = None
        for r in range(N):
            if grid[r][current_c] != '.':
                col_counts[grid[r][current_c]] += 1
                if topmost_in_col is None:
                    topmost_in_col = grid[r][current_c]
        if any(count > 1 for count in col_counts.values()):
            return False
        if topmost_in_col is not None and topmost_in_col != C[current_c]:
            return False

        # Check if we have placed too many 'A', 'B', 'C' in total for this row/col up to this point.
        # This implies we need to know how many of each character can be placed in total.
        # For each character, there must be exactly one occurence in each row and column.
        # If we have already placed a character in a row/column, we cannot place it again.
        row_placed = set()
        col_placed = set()
        for r_idx in range(N):
            for c_idx in range(N):
                if grid[r_idx][c_idx] != '.':
                    if grid[r_idx][c_idx] in row_placed and r_idx == current_r: return False
                    if grid[r_idx][c_idx] in col_placed and c_idx == current_c: return False

                    if r_idx == current_r: row_placed.add(grid[r_idx][c_idx])
                    if c_idx == current_c: col_placed.add(grid[r_idx][c_idx])

        return True

    solutions = []
    initial_grid = [['.' for _ in range(N)] for _ in range(N)]
    backtrack(0, 0, initial_grid)

    if solutions:
        print("Yes")
        for row in solutions[0]:
            print(row)
    else:
        print("No")

solve()
