def xor_of_duplicates(nums):
    """
    Returns the bitwise XOR of all numbers that appear twice in the array,
    or 0 if no number appears twice.
    """
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    xor_sum = 0
    for num, count in counts.items():
        if count == 2:
            xor_sum ^= num

    return xor_sum
